from django.db import migrations, models
from django.utils import timezone


def rellenar_situaciones(apps, schema_editor):
    """Situación de los cambios externos anteriores a este campo (25-10-2026).

    Se parte de lo que dejó el último movimiento de nómina anterior al cambio (o del
    cambio anterior, si no hubo movimiento entre medias) y se le aplica lo que el
    propio cambio anota. El último cambio de un contrato vigente sin movimientos
    después toma la situación real del contrato, que es la exacta.
    """
    from contratos.situacion import SIN_DATO, aplicar_cambio, situacion_de_contrato

    CambioExterno = apps.get_model('contratos', 'CambioExterno')
    TMovimiento = apps.get_model('contratos', 'TMovimiento')
    CAlta = apps.get_model('contratos', 'CAlta')

    pendientes = list(CambioExterno.objects.filter(situacion__isnull=True).order_by('aspirante_id', 'fecha', 'pk'))
    if not pendientes:
        return
    contratos = {c.pk: c for c in CAlta.objects.filter(
        pk__in={c.contrato_id for c in pendientes if c.contrato_id})
        .select_related('cargo__ncargo', 'cargo__departamento__unidad_organizativa')}

    def de_movimiento(m):
        return {'unidad': (m.unidad_nueva or SIN_DATO), 'departamento': (m.departamento_nuevo or SIN_DATO),
                'cargo': (m.cargo_nuevo or SIN_DATO),
                'salario': '%.2f' % float(m.salario_nuevo) if m.salario_nuevo is not None else SIN_DATO}

    por_persona = {}
    for cambio in pendientes:
        por_persona.setdefault(cambio.aspirante_id, []).append(cambio)

    for aspirante_id, cambios in por_persona.items():
        movimientos = [m for m in TMovimiento.objects.filter(aspirante_id=aspirante_id).order_by('fecha_efectiva', 'pk')
                       if 'BAJA' not in (m.tipo_movimiento or '').upper()]
        anterior = None   # (cambio, día) del cambio anterior de la persona
        for i, cambio in enumerate(cambios):
            dia = timezone.localtime(cambio.fecha).date()
            previos = [m for m in movimientos if m.fecha_efectiva and m.fecha_efectiva <= dia]
            ultimo_mov = previos[-1] if previos else None
            if (anterior is not None and anterior[0].situacion
                    and (ultimo_mov is None or ultimo_mov.fecha_efectiva <= anterior[1])):
                base = dict(anterior[0].situacion)
            elif ultimo_mov is not None:
                base = de_movimiento(ultimo_mov)
            elif cambio.contrato_id in contratos:
                base = situacion_de_contrato(contratos[cambio.contrato_id])
            else:
                base = {'unidad': SIN_DATO, 'departamento': SIN_DATO, 'cargo': SIN_DATO, 'salario': SIN_DATO}
            situacion = aplicar_cambio(base, cambio.origen, cambio.descripcion, cambio.valor_nuevo)

            es_ultimo = all(c.contrato_id != cambio.contrato_id for c in cambios[i + 1:])
            sin_movimiento_despues = not any(m.fecha_efectiva and m.fecha_efectiva > dia for m in movimientos)
            if es_ultimo and sin_movimiento_despues and cambio.contrato_id in contratos:
                situacion = situacion_de_contrato(contratos[cambio.contrato_id])

            cambio.situacion = situacion
            cambio.save(update_fields=['situacion'])
            anterior = (cambio, dia)


